/// <summary>
/// Created for the FSD - CB201 Rebates Extension - Undertake Build -  External Data Sources
/// </summary>
public class METExternalSellDataCleanupController extends SysOperationServiceController
{
}

Method.Source:
protected void new()
{
    // Call the service class and service class method
    super(classStr(METExternalSellDataCleanupService), methodStr(METExternalSellDataCleanupService, processOperation), SysOperationExecutionMode::Synchronous);
    this.parmDialogCaption("External sell data cleanup");
}

/// <summary>
/// Construct METExternalSellDataCleanupController class
/// </summary>
public static METExternalSellDataCleanupController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    METExternalSellDataCleanupController controller;
    controller = new METExternalSellDataCleanupController();
    controller.parmExecutionMode(_executionMode);

    return controller;
}

/// <summary>
/// Main method of the controller class
/// </summary>
/// <param name = "_args"></param>
public static void main(Args _args)
{
    METExternalSellDataCleanupController controller = METExternalSellDataCleanupController::construct();

    controller.parmDialogCaption("External sell data cleanup");
    controller.parmArgs(_args);
    controller.startOperation();
}
